package com.bank.spark.model;

// Captures the key signals needed to classify a Spark OOM.
public class OomSymptom {
    public enum Where { DRIVER, EXECUTOR }

    private final String job;
    private final Where where;
    private final double maxToMedianTaskRatio;  // skew signal from Stages tab
    private final boolean calledCollect;        // driver collect signal
    private final long broadcastSizeMb;         // SQL tab broadcast size

    public OomSymptom(String job, Where where, double maxToMedianTaskRatio,
                      boolean calledCollect, long broadcastSizeMb) {
        this.job = job;
        this.where = where;
        this.maxToMedianTaskRatio = maxToMedianTaskRatio;
        this.calledCollect = calledCollect;
        this.broadcastSizeMb = broadcastSizeMb;
    }

    public String getJob() { return job; }
    public Where getWhere() { return where; }
    public double getMaxToMedianTaskRatio() { return maxToMedianTaskRatio; }
    public boolean isCalledCollect() { return calledCollect; }
    public long getBroadcastSizeMb() { return broadcastSizeMb; }
}
