package com.bank.spark.service;

import com.bank.spark.model.OomSymptom;
import java.util.logging.Logger;

// Classifies the likely cause of a Spark OOM and recommends a fix.
public class OomDiagnoser {

    private static final Logger log = Logger.getLogger(OomDiagnoser.class.getName());
    private static final double SKEW_RATIO = 5.0;
    private static final long LARGE_BROADCAST_MB = 100;

    public String diagnose(OomSymptom s) {
        // Driver OOM: almost always a collect / bring-back-to-driver.
        if (s.getWhere() == OomSymptom.Where.DRIVER) {
            if (s.isCalledCollect()) {
                log.severe(() -> s.getJob() + ": driver OOM from collect() on large data");
                return "DRIVER collect() — write to storage or use take/limit, never collect large data";
            }
            log.severe(() -> s.getJob() + ": driver OOM (check broadcast assembly / accumulators)");
            return "DRIVER OOM — inspect broadcast assembly and driver-side accumulation";
        }
        // Executor OOM: skew first, then broadcast.
        if (s.getMaxToMedianTaskRatio() >= SKEW_RATIO) {
            log.severe(() -> s.getJob() + ": executor OOM from SKEW (max/median="
                    + s.getMaxToMedianTaskRatio() + ")");
            return "DATA SKEW — enable AQE skew join, salt, or isolate-and-broadcast the hot key";
        }
        if (s.getBroadcastSizeMb() >= LARGE_BROADCAST_MB) {
            log.severe(() -> s.getJob() + ": executor OOM from oversized broadcast "
                    + s.getBroadcastSizeMb() + "MB");
            return "OVERSIZED BROADCAST — disable broadcast for this join / lower threshold";
        }
        log.warning(() -> s.getJob() + ": executor OOM, no skew/broadcast → likely too few partitions");
        return "TOO FEW PARTITIONS / HEAVY SHUFFLE — raise shuffle.partitions, prune before shuffle";
    }
}
