package com.bank.spark;

import com.bank.spark.model.OomSymptom;
import com.bank.spark.service.OomDiagnoser;
import java.util.List;
import java.util.logging.ConsoleHandler;
import java.util.logging.Formatter;
import java.util.logging.Level;
import java.util.logging.LogRecord;
import java.util.logging.Logger;

// Runnable demo: classify several OOM symptoms into cause + fix.
public class OomDiagnosticsDemo {

    private static final Logger log = Logger.getLogger(OomDiagnosticsDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (var h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler handler = new ConsoleHandler();
        handler.setLevel(Level.ALL);
        handler.setFormatter(new Formatter() {
            @Override public String format(LogRecord r) {
                return String.format("%1$tF %1$tT %2$-7s %3$s%n",
                        new java.util.Date(r.getMillis()), r.getLevel(), r.getMessage());
            }
        });
        root.addHandler(handler);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        OomDiagnoser diag = new OomDiagnoser();

        List<OomSymptom> cases = List.of(
            new OomSymptom("txn-join", OomSymptom.Where.EXECUTOR, 50.0, false, 5),
            new OomSymptom("daily-report", OomSymptom.Where.DRIVER, 1.0, true, 0),
            new OomSymptom("ref-join", OomSymptom.Where.EXECUTOR, 1.2, false, 400),
            new OomSymptom("wide-agg", OomSymptom.Where.EXECUTOR, 1.1, false, 2));

        for (OomSymptom s : cases) {
            String fix = diag.diagnose(s);
            log.info(() -> "Job " + s.getJob() + " → " + fix);
        }
        log.info("OOM diagnostics demo complete.");
    }
}
